const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_board_card

async function ui_board_card (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
    /* COMMENTED CONSUMER EMITTER FOR EXTRACTING SYNCED DATA STREAMS
    data: update
    */
  }

  const { io, _ } = net(id)

  io.on = {
    up: onmessage
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="board-card">
      <div class="preview-grid">
        <div class="main-thumb">
          <span class="placeholder-icon"></span>
       
        </div>
        <div class="sub-thumbs">
          <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
          <div class="sub-thumb"><span class="placeholder-icon smaller"></span></div>
          <div class="edit-badge"><span class="brush-icon"></span></div>
        </div>
      </div>
      <div class="card-meta">
        <h3 class="card-title">Card Title</h3>
        <p class="card-count">100 Pins</p>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  /*
  const card_title = shadow.querySelector('.card-title')
  const card_count = shadow.querySelector('.card-count')
  const edit_badge = shadow.querySelector('.edit-badge')
  */
  const brush_icon = shadow.querySelector('.brush-icon')
  const placeholders = shadow.querySelectorAll('.placeholder-icon')

  await sdb.watch(onbatch)

  if (invite) io.accept(invite)

  shadow.querySelector('.board-card').onclick = () => {
    _.up('card_clicked', { sid: opts.sid }, {})
  }

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  // FIXED: Adjusted array destructing offsets to properly align incoming mapped asset paths
  function iconject ({ data }) {
    const imagePlaceholderSvg = data[0] || ''
    const brushSvg = data[1] || ''
    
    if (brush_icon && brushSvg) brush_icon.innerHTML = brushSvg
    if (imagePlaceholderSvg) {
      placeholders.forEach(span => {
        span.innerHTML = imagePlaceholderSvg
      })
    }
  }

  /* 
  function update ({ data }) {
    try {
      if (!data || !data.length) return
      const targetRaw = data.find(item => item && item.includes('title')) || data[0]
      const state = typeof targetRaw === 'string' ? JSON.parse(targetRaw) : targetRaw
      if (!state) return

      if (card_title && state.title) card_title.textContent = state.title
      if (card_count && state.count) card_count.textContent = state.count
      
      if (edit_badge) {
        if (state.has_badge) {
          edit_badge.classList.remove('hidden')
        } else {
          edit_badge.classList.add('hidden')
        }
      }
    } catch (err) {
      console.error('ui_board_card state parse error:', err)
    }
  }
  */

  function onmessage (msg) {
    console.log('ui_board_card:', msg.type)
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: {
          0: ''
        }
      },
      drive: {
        'icons/': {
          'image_placeholder.svg': { $ref: 'image_placeholder.svg' },
          'brush.svg': { $ref: 'brush.svg' }
        },
        'style/ui_board_card.css': {
          $ref: 'ui_board_card.css'
        }
      }
    }
  }
}